mapper.select:
SELECT COUNT(*)
FROM quant_trade_log
WHERE strategy_id = #{strategyId}
  AND from_date = #{fromDate}
  AND to_date = #{toDate}

      AND trade_type = #{tradeType}

SELECT id, strategy_id AS strategyId, from_date AS fromDate, to_date AS toDate,
       trade_date AS tradeDate, asset_code AS assetCode, asset_name AS assetName,
       asset_type AS assetType, trade_type AS tradeType, price, quantity, amount,
       weight, reason, commission, tax, created_at AS createdAt
FROM quant_trade_log
WHERE strategy_id = #{strategyId}
  AND from_date = #{fromDate}
  AND to_date = #{toDate}

      AND trade_type = #{tradeType}

ORDER BY trade_date DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.delete:
DELETE FROM quant_trade_log
WHERE strategy_id = #{strategyId}
  AND from_date = #{fromDate}
  AND to_date = #{toDate}

DELETE FROM quant_trade_log
WHERE from_date <= #{toDate}
  AND to_date >= #{fromDate}
